def sum_with_index_operations(numbers):
    from functools import reduce

    def operation(index, number):
        if index % 3 == 0:
            return number ** 2
        elif index % 4 == 0:
            return number ** 3
        else:
            return number

    return reduce(
        lambda acc, item: acc + operation(item[0], item[1]),
        enumerate(numbers),
        0
    )

