def by_length(arr):
    """
    Processes a list of integers, filtering for values between 1 and 9 inclusive.
    Sorts the list in descending order and converts each valid integer to its 
    English word representation.
    """
    # Mapping of integers to their English word representation
    word_map = {
        1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five",
        6: "Six", 7: "Seven", 8: "Eight", 9: "Nine"
    }

    # Functional pipeline: filter -> sort -> map
    return list(
        map(
            lambda x: word_map[x],
            sorted(
                filter(lambda x: 1 <= x <= 9, arr),
                reverse=True
            )
        )
    )
