def triangle_area(a, b, c):
    # Check triangle inequality
    if a + b <= c or a + c <= b or b + c <= a:
        return -1

    p = (a + b + c) / 2.0
    area squared = p * (p - a) * (p - b) * (p - c)  # compute under radical

    # Ensure non-negative due to floating point errors
    area_squared = max(0.0, area_squared)
    area = area_squared ** 0.5
    return round(area, 2)

def prime_factors(n):
    """Return the list of prime factors of n in non-decreasing order."""
    factors = []
    # handle 2s
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    # odd factors
    p = 3
    while p * p <= n:
        while n % p == 0:
            factors.append(p)
            n //= p
        p += 2
    if n > 1:
        factors.append(n)
    return factors

